import React, { useState, useEffect, useRef, useCallback } from 'react';
import { GoogleGenAI, LiveServerMessage, Modality } from '@google/genai';
import { decode, decodeAudioData, createBlob } from '../utils/audio';
import { ConnectionStatus, Message } from '../types';

interface AssistantPanelProps {
  onMessage: (role: 'user' | 'assistant', text: string) => void;
  messages: Message[];
}

export const AssistantPanel: React.FC<AssistantPanelProps> = ({ onMessage, messages }) => {
  const [status, setStatus] = useState<ConnectionStatus>(ConnectionStatus.DISCONNECTED);
  const [isSpeaking, setIsSpeaking] = useState(false);
  const [transcription, setTranscription] = useState('');
  const chatEndRef = useRef<HTMLDivElement>(null);

  // Audio Refs
  const audioContextRef = useRef<AudioContext | null>(null);
  const outputAudioContextRef = useRef<AudioContext | null>(null);
  const nextStartTimeRef = useRef(0);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const sessionPromiseRef = useRef<Promise<any> | null>(null);

  const SYSTEM_INSTRUCTION = `
    You are CASWA-EdVisor (pronounced "KASWAA-EdVisor"), the official Female AI Voice Assistant and Digital Guide of CASWA Model Science School (CMSS), Jacobabad, Pakistan.

    🌸 IDENTITY & GREETING
    - You are female in voice, tone, and conversational style.
    - Always start the conversation with: "Assalam-o-Alaikum! I am CASWA-EdVisor, the digital guide of CASWA Model Science School."
    - Pronounce CASWA clearly as "KASWAA".
    - Represent the school warmly, respectfully, and professionally.

    🎯 CORE RESPONSIBILITIES
    - Guide parents, students, teachers, and visitors about admissions, eligibility, fee structure, curriculum (KG1 to Grade 12), STEM, Robotics, AI, Entrepreneurship, and child protection.
    - Share accurate information about CASWA.
    - Encourage parents to visit school and contact admin.

    🏫 SCHOOL CONTEXT
    - Location: Wagha Street, near Jamia Pir Bukhari Masjid, Jacobabad, Sindh.
    - Maps Link: https://share.google/cBlgOF9GJC4MRoUwG
    - Admission Link: https://sites.google.com/view/caswa-model-science-school/home
    - WhatsApp: +92 332 2875909
    - Email: cmss@caswa.org.pk
    - Web: www.cmss.edu.pk

    🗣️ STYLE
    - Warm, polite, professional female tone.
    - Default language: Simple English.
    - Reply in Urdu/Roman Urdu if the user speaks it. natural mixing is okay.
    - Keep responses short, clear, and parent-friendly.

    📲 LEAD COLLECTION
    - Politely try to collect the visitor's contact number: "Agar aap ijazat dein, kya main aap ka contact number le sakti hoon taake school administration aapse admissions ke liye rabta kar sake?"

    ⚠️ RULES
    - Do NOT guess. If unsure, say: "Is hawalay se behtar maloomat ke liye barah-e-karam school office se rabta karein."
  `;

  const scrollToBottom = () => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages, transcription]);

  const startAssistant = async () => {
    if (status !== ConnectionStatus.DISCONNECTED) return;

    try {
      setStatus(ConnectionStatus.CONNECTING);
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      outputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        callbacks: {
          onopen: () => {
            setStatus(ConnectionStatus.CONNECTED);
            const source = audioContextRef.current!.createMediaStreamSource(stream);
            const scriptProcessor = audioContextRef.current!.createScriptProcessor(4096, 1, 1);

            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const pcmBlob = createBlob(inputData);
              sessionPromise.then(session => session.sendRealtimeInput({ media: pcmBlob }));
            };

            source.connect(scriptProcessor);
            scriptProcessor.connect(audioContextRef.current!.destination);
          },
          onmessage: async (message: LiveServerMessage) => {
            if (message.serverContent?.outputTranscription) {
              setTranscription(prev => prev + message.serverContent!.outputTranscription!.text);
            }

            if (message.serverContent?.turnComplete) {
              setTranscription(t => {
                if (t.trim()) onMessage('assistant', t);
                return '';
              });
            }

            const base64Audio = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (base64Audio) {
              setIsSpeaking(true);
              const ctx = outputAudioContextRef.current!;
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);

              const audioBuffer = await decodeAudioData(decode(base64Audio), ctx, 24000, 1);
              const source = ctx.createBufferSource();
              source.buffer = audioBuffer;
              source.connect(ctx.destination);
              source.addEventListener('ended', () => {
                sourcesRef.current.delete(source);
                if (sourcesRef.current.size === 0) setIsSpeaking(false);
              });
              source.start(nextStartTimeRef.current);
              nextStartTimeRef.current += audioBuffer.duration;
              sourcesRef.current.add(source);
            }

            if (message.serverContent?.interrupted) {
              sourcesRef.current.forEach(s => s.stop());
              sourcesRef.current.clear();
              nextStartTimeRef.current = 0;
              setIsSpeaking(false);
            }
          },
          onerror: (e) => {
            console.error('Gemini error:', e);
            setStatus(ConnectionStatus.ERROR);
          },
          onclose: () => {
            setStatus(ConnectionStatus.DISCONNECTED);
          }
        },
        config: {
          responseModalities: [Modality.AUDIO],
          systemInstruction: SYSTEM_INSTRUCTION,
          speechConfig: {
            voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } },
          },
          outputAudioTranscription: {},
        }
      });

      sessionPromiseRef.current = sessionPromise;
    } catch (err) {
      console.error(err);
      setStatus(ConnectionStatus.ERROR);
    }
  };

  const stopAssistant = () => {
    if (sessionPromiseRef.current) {
      sessionPromiseRef.current.then(s => s.close());
      sessionPromiseRef.current = null;
    }
    if (audioContextRef.current) audioContextRef.current.close();
    if (outputAudioContextRef.current) outputAudioContextRef.current.close();
    setStatus(ConnectionStatus.DISCONNECTED);
    setIsSpeaking(false);
  };

  return (
    <div className="bg-white rounded-3xl shadow-2xl overflow-hidden border border-rose-100 flex flex-col h-[500px]">
      {/* Visual Header */}
      <div className="bg-slate-900 px-6 py-4 flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className="relative">
            <div className={`w-10 h-10 rounded-full bg-rose-500 flex items-center justify-center text-white text-lg font-bold ${isSpeaking ? 'animate-pulse scale-110' : ''} transition-all`}>
              CE
            </div>
            {status === ConnectionStatus.CONNECTED && (
              <span className="absolute bottom-0 right-0 w-3 h-3 bg-green-500 border-2 border-slate-900 rounded-full"></span>
            )}
          </div>
          <div>
            <p className="text-white font-bold leading-tight">CASWA Ed-Visor</p>
            <p className="text-xs text-rose-300 font-medium">
              {status === ConnectionStatus.CONNECTED ? 'Listening...' : status === ConnectionStatus.CONNECTING ? 'Connecting...' : 'Ready to help'}
            </p>
          </div>
        </div>

        {status === ConnectionStatus.CONNECTED ? (
          <button 
            onClick={stopAssistant}
            className="p-2 bg-rose-500/20 text-rose-400 hover:bg-rose-500 hover:text-white rounded-full transition-all"
            title="Disconnect"
          >
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"></path></svg>
          </button>
        ) : (
          <button 
            onClick={startAssistant}
            className="px-4 py-2 bg-rose-600 hover:bg-rose-700 text-white text-sm font-bold rounded-full transition-all flex items-center gap-2 shadow-lg"
          >
            <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 20 20"><path d="M7 4a3 3 0 016 0v4a3 3 0 11-6 0V4zm4 10.93A7.001 7.001 0 0017 8a1 1 0 10-2 0A5 5 0 015 8a1 1 0 00-2 0 7.001 7.001 0 006 6.93V17H6a1 1 0 100 2h8a1 1 0 100-2h-3v-2.07z"></path></svg>
            Start Assistant
          </button>
        )}
      </div>

      {/* Messages / Interaction area */}
      <div className="flex-grow overflow-y-auto p-6 space-y-4 bg-slate-50/50">
        {messages.length === 0 && !transcription && (
          <div className="flex flex-col items-center justify-center h-full text-center space-y-4 text-slate-400">
            <div className="w-16 h-16 bg-white rounded-full shadow-inner flex items-center justify-center border border-slate-100">
              🎙️
            </div>
            <p className="max-w-[200px] text-sm font-medium">
              Tap "Start Assistant" and say "Assalam-o-Alaikum" to begin the conversation.
            </p>
          </div>
        )}

        {messages.map((m) => (
          <div key={m.id} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[80%] rounded-2xl px-4 py-3 shadow-sm ${
              m.role === 'user' 
                ? 'bg-rose-600 text-white rounded-tr-none' 
                : 'bg-white text-slate-800 border border-slate-100 rounded-tl-none'
            }`}>
              <p className="text-sm leading-relaxed">{m.text}</p>
              <p className={`text-[10px] mt-1 opacity-50 ${m.role === 'user' ? 'text-white' : 'text-slate-500'}`}>
                {m.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
              </p>
            </div>
          </div>
        ))}

        {transcription && (
          <div className="flex justify-start">
            <div className="bg-white/80 border border-slate-100 text-slate-600 max-w-[80%] rounded-2xl px-4 py-3 animate-pulse">
              <p className="text-sm italic">{transcription}...</p>
            </div>
          </div>
        )}
        <div ref={chatEndRef} />
      </div>

      {/* Footer Visualizer */}
      <div className="h-1 bg-slate-100">
        {isSpeaking && (
          <div className="h-full bg-rose-500 animate-[shimmer_2s_infinite_linear]" style={{ backgroundSize: '200% 100%', backgroundImage: 'linear-gradient(90deg, #f43f5e 0%, #fb7185 50%, #f43f5e 100%)' }}></div>
        )}
      </div>
    </div>
  );
};

