import React, { useState } from 'react';

interface LeadFormProps {
  onComplete: () => void;
}

export const LeadForm: React.FC<LeadFormProps> = ({ onComplete }) => {
  const [phone, setPhone] = useState('');
  const [name, setName] = useState('');
  const [submitted, setSubmitted] = useState(false);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    // Simulate API call to save lead
    setSubmitted(true);
    setTimeout(() => {
      onComplete();
    }, 3000);
  };

  if (submitted) {
    return (
      <div className="p-8 text-center space-y-3 bg-green-50 rounded-2xl border border-green-100">
        <div className="w-12 h-12 bg-green-500 rounded-full flex items-center justify-center text-white mx-auto text-xl">
          ✓
        </div>
        <h3 className="text-xl font-bold text-green-800">Shukriya!</h3>
        <p className="text-sm text-green-600">
          Humara school administration jald hi aapse rabta karega.
        </p>
      </div>
    );
  }

  return (
    <form onSubmit={handleSubmit} className="space-y-4 p-4 bg-slate-50 rounded-2xl border border-slate-100">
      <h3 className="text-lg font-bold text-slate-800">Inquiry Request</h3>
      <p className="text-xs text-slate-500 mb-4">Leave your contact for a callback from the administration.</p>

      <div>
        <label className="block text-xs font-bold text-slate-400 uppercase tracking-wider mb-1">Your Name</label>
        <input 
          type="text" 
          required
          value={name}
          onChange={(e) => setName(e.target.value)}
          placeholder="Enter parent or student name"
          className="w-full px-4 py-2 bg-white border border-slate-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-rose-500/20 focus:border-rose-500"
        />
      </div>

      <div>
        <label className="block text-xs font-bold text-slate-400 uppercase tracking-wider mb-1">WhatsApp / Contact Number</label>
        <input 
          type="tel" 
          required
          value={phone}
          onChange={(e) => setPhone(e.target.value)}
          placeholder="+92 3XX XXXXXXX"
          className="w-full px-4 py-2 bg-white border border-slate-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-rose-500/20 focus:border-rose-500"
        />
      </div>

      <button 
        type="submit"
        className="w-full py-2 bg-slate-900 text-white text-sm font-bold rounded-lg hover:bg-slate-800 transition-all shadow-md"
      >
        Send Details
      </button>
    </form>
  );
};

