              source.start(nextStartTimeRef.current);
              nextStartTimeRef.current += audioBuffer.duration;
              sourcesRef.current.add(source);
            }
            if (message.serverContent?.interrupted) {
              sourcesRef.current.forEach(s => s.stop());
              sourcesRef.current.clear();
              nextStartTimeRef.current = 0;
              setIsSpeaking(false);
            }
          },
          onerror: (e) => { setStatus(ConnectionStatus.ERROR); },
          onclose: () => { setStatus(ConnectionStatus.DISCONNECTED); }
        },
        config: {
          responseModalities: [Modality.AUDIO],
          systemInstruction: SYSTEM_INSTRUCTION,
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } },
          outputAudioTranscription: {},
        }
      });
      sessionPromiseRef.current = sessionPromise;
    } catch (err) {
      setStatus(ConnectionStatus.ERROR);
    }
  };

  const stopAssistant = () => {
    if (sessionPromiseRef.current) sessionPromiseRef.current.then(s => s.close());
    if (audioContextRef.current) audioContextRef.current.close();
    if (outputAudioContextRef.current) outputAudioContextRef.current.close();
    setStatus(ConnectionStatus.DISCONNECTED);
    setIsSpeaking(false);
  };

  return (
    <div className="bg-white rounded-[2rem] shadow-2xl overflow-hidden border border-blue-100 flex flex-col h-[600px] transition-all">
      {/* Central Title Section */}
      <div className="bg-white py-8 px-6 text-center border-b border-blue-50">
        <h2 className="text-4xl md:text-5xl font-black text-[#002147] mb-2 tracking-tight">
          CASWA-EdVisor
        </h2>
        <p className="text-blue-500 font-semibold tracking-widest text-xs uppercase">
          Digital Guide & Assistant
        </p>
      </div>

      {/* Interaction Area */}
      <div className="flex-grow overflow-y-auto p-6 space-y-4 bg-slate-50/30">
        {messages.length === 0 && !transcription && (
          <div className="flex flex-col items-center justify-center h-full text-center space-y-6">
            <div className="p-4 bg-blue-50 rounded-full border border-blue-100 max-w-xs">
              <p className="text-[#002147] text-sm font-medium">
                "Assalam-o-Alaikum! How can I help you with admissions or school information today?"
              </p>
            </div>
          </div>
        )}

        {messages.map((m) => (
          <div key={m.id} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[85%] rounded-2xl px-5 py-3 shadow-sm ${
              m.role === 'user' 
                ? 'bg-[#002147] text-white rounded-tr-none' 
                : 'bg-white text-slate-800 border border-blue-50 rounded-tl-none'
            }`}>
              <p className="text-sm leading-relaxed">{m.text}</p>
              <p className={`text-[10px] mt-1 opacity-60 font-bold ${m.role === 'user' ? 'text-blue-200' : 'text-[#002147]'}`}>
