            <button 
              onClick={stopAssistant}
              className="w-20 h-20 bg-red-500 text-white rounded-full flex items-center justify-center shadow-xl hover:bg-red-600 transition-all transform active:scale-95 group"
              aria-label="Stop"
            >
              <svg className="w-8 h-8" fill="currentColor" viewBox="0 0 20 20">
                <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zM8 7a1 1 0 00-1 1v4a1 1 0 001 1h4a1 1 0 001-1V8a1 1 0 00-1-1H8z" clipRule="evenodd" />
              </svg>
            </button>
          ) : (
            <button 
              onClick={startAssistant}
              disabled={status === ConnectionStatus.CONNECTING}
              className={`w-24 h-24 rounded-full flex flex-col items-center justify-center shadow-2xl transition-all transform active:scale-95 ${
                status === ConnectionStatus.CONNECTING 
                  ? 'bg-blue-100 text-blue-300 animate-pulse' 
                  : 'bg-[#002147] text-white hover:bg-blue-800'
              }`}
            >
              <svg className="w-10 h-10 mb-1" fill="currentColor" viewBox="0 0 20 20">
                <path d="M7 4a3 3 0 016 0v4a3 3 0 11-6 0V4zm4 10.93A7.001 7.001 0 0017 8a1 1 0 10-2 0A5 5 0 015 8a1 1 0 00-2 0 7.001 7.001 0 006 6.93V17H6a1 1 0 100 2h8a1 1 0 100-2h-3v-2.07z" />
              </svg>
              <span className="text-[10px] font-black uppercase tracking-widest">
                {status === ConnectionStatus.CONNECTING ? '...' : 'Speak'}
              </span>
            </button>
          )}

          <div className="text-center">
            <p className={`text-sm font-bold transition-colors ${status === ConnectionStatus.CONNECTED ? 'text-blue-600' : 'text-slate-400'}`}>
              {status === ConnectionStatus.CONNECTED ? 'Microphone Active' : status === ConnectionStatus.CONNECTING ? 'Establishing Connection...' : 'Tap Microphone to Start'}
            </p>
          </div>
        </div>
      </div>
    </div>
  );
};

