import React, { useState, useEffect, useRef } from 'react';
import { GoogleGenAI, LiveServerMessage, Modality } from '@google/genai';
import { decode, decodeAudioData, createBlob } from '../utils/audio';
import { ConnectionStatus, Message } from '../types';

interface AssistantPanelProps {
  onMessage: (role: 'user' | 'assistant', text: string) => void;
  messages: Message[];
}

export const AssistantPanel: React.FC<AssistantPanelProps> = ({ onMessage, messages }) => {
  const [status, setStatus] = useState<ConnectionStatus>(ConnectionStatus.DISCONNECTED);
  const [isSpeaking, setIsSpeaking] = useState(false);
  const [transcription, setTranscription] = useState('');
  const chatEndRef = useRef<HTMLDivElement>(null);

  const audioContextRef = useRef<AudioContext | null>(null);
  const outputAudioContextRef = useRef<AudioContext | null>(null);
  const nextStartTimeRef = useRef(0);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const sessionPromiseRef = useRef<Promise<any> | null>(null);

  const SYSTEM_INSTRUCTION = `
    You are CASWA-EdVisor (pronounced "KASWAA-EdVisor"), the official Female AI Voice Assistant and Digital Guide of CASWA Model Science School (CMSS), Jacobabad, Pakistan.
    🌸 IDENTITY & GREETING: Female voice. Always start with: "Assalam-o-Alaikum! I am CASWA-EdVisor, the digital guide of CASWA Model Science School."
    🏫 CONTEXT: Jacobabad, Sindh. Admissions Mar 15 - Mar 30. STEM/Robotics focus.
    🗣️ STYLE: Warm, polite, professional. English/Urdu mix allowed.
    📲 LEAD: Collect contact number politely for admissions.
  `;

  const scrollToBottom = () => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages, transcription]);

  const startAssistant = async () => {
    if (status !== ConnectionStatus.DISCONNECTED) return;
    try {
      setStatus(ConnectionStatus.CONNECTING);
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      outputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        callbacks: {
          onopen: () => {
            setStatus(ConnectionStatus.CONNECTED);
            const source = audioContextRef.current!.createMediaStreamSource(stream);
            const scriptProcessor = audioContextRef.current!.createScriptProcessor(4096, 1, 1);
            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const pcmBlob = createBlob(inputData);
              sessionPromise.then(session => session.sendRealtimeInput({ media: pcmBlob }));
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(audioContextRef.current!.destination);
          },
          onmessage: async (message: LiveServerMessage) => {
            if (message.serverContent?.outputTranscription) {
              setTranscription(prev => prev + message.serverContent!.outputTranscription!.text);
            }
            if (message.serverContent?.turnComplete) {
              setTranscription(t => { if (t.trim()) onMessage('assistant', t); return ''; });
            }
            const base64Audio = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (base64Audio) {
              setIsSpeaking(true);
              const ctx = outputAudioContextRef.current!;
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);
              const audioBuffer = await decodeAudioData(decode(base64Audio), ctx, 24000, 1);
              const source = ctx.createBufferSource();
              source.buffer = audioBuffer;
              source.connect(ctx.destination);
              source.addEventListener('ended', () => {
                sourcesRef.current.delete(source);
                if (sourcesRef.current.size === 0) setIsSpeaking(false);
              });
              source.start(nextStartTimeRef.current);
              nextStartTimeRef.current += audioBuffer.duration;
              sourcesRef.current.add(source);
            }
            if (message.serverContent?.interrupted) {
              sourcesRef.current.forEach(s => s.stop());
              sourcesRef.current.clear();
              nextStartTimeRef.current = 0;
              setIsSpeaking(false);
            }
          },
          onerror: (e) => { setStatus(ConnectionStatus.ERROR); },
          onclose: () => { setStatus(ConnectionStatus.DISCONNECTED); }
        },
        config: {
          responseModalities: [Modality.AUDIO],
          systemInstruction: SYSTEM_INSTRUCTION,
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } },
          outputAudioTranscription: {},
        }
      });
      sessionPromiseRef.current = sessionPromise;
    } catch (err) {
      setStatus(ConnectionStatus.ERROR);
    }
  };

  const stopAssistant = () => {
    if (sessionPromiseRef.current) sessionPromiseRef.current.then(s => s.close());
    if (audioContextRef.current) audioContextRef.current.close();
    if (outputAudioContextRef.current) outputAudioContextRef.current.close();
    setStatus(ConnectionStatus.DISCONNECTED);
    setIsSpeaking(false);
  };

  return (
    <div className="bg-white rounded-[2.5rem] shadow-2xl overflow-hidden border border-blue-100 flex flex-col h-[700px] transition-all">
      {/* Top Row: School Name */}
      <div className="bg-[#002147] py-4 px-6 text-center">
        <h3 className="text-white text-xs font-black uppercase tracking-[0.3em]">
          CASWA Model Science School
        </h3>
      </div>

      {/* Middle: Big Font Title */}
      <div className="bg-white pt-10 pb-6 px-6 text-center">
        <h2 className="text-5xl md:text-6xl font-black text-[#002147] tracking-tighter">
          CASWA-EdVisor
        </h2>
        <p className="text-blue-500 font-bold tracking-widest text-xs uppercase mt-2">
          Official Digital Guide
        </p>
      </div>

      {/* Interaction Area & Large Microphone */}
      <div className="flex-grow relative overflow-y-auto p-6 space-y-4 bg-slate-50/30">
        {messages.length === 0 && !transcription ? (
          <div className="flex flex-col items-center justify-center h-full">
            <div className="relative group">
              {/* Pulsing rings when connected or idle */}
              <div className={`absolute inset-0 rounded-full bg-blue-400/20 scale-150 blur-xl ${status === ConnectionStatus.CONNECTED ? 'animate-pulse' : ''}`}></div>
              <div className={`absolute inset-0 rounded-full bg-blue-400/10 scale-[2] blur-2xl ${status === ConnectionStatus.CONNECTED ? 'animate-ping' : ''}`}></div>

              <button 
                onClick={status === ConnectionStatus.CONNECTED ? stopAssistant : startAssistant}
                disabled={status === ConnectionStatus.CONNECTING}
                className={`relative z-10 w-40 h-40 rounded-full flex flex-col items-center justify-center shadow-2xl transition-all transform hover:scale-105 active:scale-95 ${
                  status === ConnectionStatus.CONNECTED 
                    ? 'bg-red-500 text-white' 
                    : status === ConnectionStatus.CONNECTING 
                      ? 'bg-blue-100 text-blue-300 cursor-wait' 
                      : 'bg-[#002147] text-white'
                }`}
              >
                {status === ConnectionStatus.CONNECTED ? (
                  <svg className="w-16 h-16" fill="currentColor" viewBox="0 0 20 20">
                    <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zM8 7a1 1 0 00-1 1v4a1 1 0 001 1h4a1 1 0 001-1V8a1 1 0 00-1-1H8z" clipRule="evenodd" />
                  </svg>
                ) : (
                  <svg className="w-16 h-16 mb-2" fill="currentColor" viewBox="0 0 20 20">
                    <path d="M7 4a3 3 0 016 0v4a3 3 0 11-6 0V4zm4 10.93A7.001 7.001 0 0017 8a1 1 0 10-2 0A5 5 0 015 8a1 1 0 00-2 0 7.001 7.001 0 006 6.93V17H6a1 1 0 100 2h8a1 1 0 100-2h-3v-2.07z" />
                  </svg>
                )}
                <span className="text-xs font-black uppercase tracking-widest">
                  {status === ConnectionStatus.CONNECTED ? 'STOP' : status === ConnectionStatus.CONNECTING ? '...' : 'TALK TO ME'}
                </span>
              </button>
            </div>

            <p className="mt-8 text-[#002147] font-bold text-sm tracking-wide opacity-50 uppercase">
              {status === ConnectionStatus.CONNECTED ? 'I am listening...' : 'Tap to start conversation'}
            </p>
          </div>
        ) : (
          <div className="flex flex-col gap-4">
            {messages.map((m) => (
              <div key={m.id} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                <div className={`max-w-[85%] rounded-2xl px-5 py-3 shadow-sm ${
                  m.role === 'user' 
                    ? 'bg-[#002147] text-white rounded-tr-none' 
                    : 'bg-white text-slate-800 border border-blue-50 rounded-tl-none'
                }`}>
                  <p className="text-sm leading-relaxed">{m.text}</p>
                  <p className={`text-[10px] mt-1 opacity-60 font-bold ${m.role === 'user' ? 'text-blue-200' : 'text-[#002147]'}`}>
                    {m.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                  </p>
                </div>
              </div>
            ))}
            {transcription && (
              <div className="flex justify-start">
                <div className="bg-white/90 border border-blue-100 text-[#002147] max-w-[85%] rounded-2xl px-5 py-3 animate-pulse italic text-sm">
                  {transcription}...
                </div>
              </div>
            )}
            <div ref={chatEndRef} />
          </div>
        )}
      </div>

      {/* Mini Control Bar when chatting */}
      {(messages.length > 0 || transcription) && (
        <div className="p-4 bg-white border-t border-blue-50 flex items-center justify-between">
           <div className="flex items-center gap-2">
            <div className={`w-3 h-3 rounded-full ${status === ConnectionStatus.CONNECTED ? 'bg-green-500 animate-pulse' : 'bg-slate-300'}`}></div>
            <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Live Session</span>
          </div>
          <button 
            onClick={status === ConnectionStatus.CONNECTED ? stopAssistant : startAssistant}
            className={`w-12 h-12 rounded-full flex items-center justify-center shadow-lg transition-all ${
              status === ConnectionStatus.CONNECTED ? 'bg-red-500 text-white' : 'bg-[#002147] text-white'
            }`}
          >
            {status === ConnectionStatus.CONNECTED ? (
              <svg className="w-6 h-6" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zM8 7a1 1 0 00-1 1v4a1 1 0 001 1h4a1 1 0 001-1V8a1 1 0 00-1-1H8z" clipRule="evenodd" /></svg>
            ) : (
              <svg className="w-6 h-6" fill="currentColor" viewBox="0 0 20 20"><path d="M7 4a3 3 0 016 0v4a3 3 0 11-6 0V4zm4 10.93A7.001 7.001 0 0017 8a1 1 0 10-2 0A5 5 0 015 8a1 1 0 00-2 0 7.001 7.001 0 006 6.93V17H6a1 1 0 100 2h8a1 1 0 100-2h-3v-2.07z" /></svg>
            )}
          </button>
        </div>
      )}
    </div>
  );
};

